  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    @store[key] = Entry.new(
      packer ? packer.dump(payload) : payload,
      stale
    )
    nil
  end

  def read(key)
    entry = @store[key]
    return nil if entry.nil?
    unpack(entry.payload)
  end

  def sweep
    @store.delete_if do |_key, entry|
      entry.stale
    end
    nil
  end

  private

  def packer
    @packer
  end

  def pack(payload)
    packer ? packer.dump(payload) : payload
  end

  def unpack(data)
