      raise ArgumentError, "cannot compare Weights of different units: #{@unit.inspect} vs #{other.unit.inspect}"
    end

    @amount <=> other.amount
  end

  def ==(other)
    return false unless other.is_a?(Weight)
    @amount == other.amount && @unit == other.unit
  end
end
